package com.example.vendorchat.ui

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/** آیکن‌های Material Symbols (Rounded, Filled) به صورت ImageVector؛ مسیرها از مخزن رسمی Google گرفته شده‌اند. */
private fun sym(name: String, vararg paths: String): ImageVector {
    val b = ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f)
    b.addGroup(translationY = 960f)
    for (p in paths) b.addPath(pathData = PathParser().parsePathString(p).toNodes(), fill = SolidColor(Color.Black))
    b.clearGroup()
    return b.build()
}

